package main
import("fmt";"go/ast";"go/parser";"go/token";"os";"path/filepath";"strings";"sort")
type D struct{ name,path string; recv bool; n int }
func main(){fs:=token.NewFileSet(); ds:=map[string][]*D{}; files:=[]string{}; filepath.Walk(".",func(p string,i os.FileInfo,e error)error{if e==nil&&strings.HasSuffix(p,".go")&&!strings.Contains(p,"/vendor/"){files=append(files,p)};return nil}); for _,p:=range files {f,e:=parser.ParseFile(fs,p,nil,0);if e!=nil{continue}; under:=strings.HasPrefix(p,"internal/"); if under {for _,d:=range f.Decls {if fn,ok:=d.(*ast.FuncDecl);ok {name:=fn.Name.Name; recv:=fn.Recv!=nil; ds[name]=append(ds[name],&D{name,p,recv,0})}}}}
 for _,p:=range files {f,e:=parser.ParseFile(fs,p,nil,0);if e!=nil{continue}; ast.Inspect(f,func(n ast.Node)bool{c,ok:=n.(*ast.CallExpr);if !ok{return true}; var name string; switch x:=c.Fun.(type){case *ast.Ident:name=x.Name;case *ast.SelectorExpr:name=x.Sel.Name}; if name!="" {for _,d:=range ds[name]{d.n++}}; return true})}; out:=[]*D{};for _,a:=range ds{out=append(out,a...)};sort.Slice(out,func(i,j int)bool{return out[i].n>out[j].n});for i,d:=range out {if i>=30{break};fmt.Printf("%d %s %s recv=%v\n",d.n,d.name,d.path,d.recv)} }

